Tool response:
Tool: lookup_programs
Description: Lookup Programs
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Partial or exact match for program name",
          "title": "Name"
        },
        "code": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Exact match for program code",
          "title": "Code"
        }
      },
      "required": []
    }

Tool response:
Tool: create_recommendation_requirement
Description: Create Recommendation Requirement
Parameters:
    {
      "type": "object",
      "properties": {
        "program_id": {
          "type": "integer",
          "title": "Program Id",
          "description": ""
        },
        "requirement_type": {
          "type": "string",
          "title": "Requirement Type",
          "description": "Type of recommender: 'Science Faculty', 'Clinical Supervisor', or 'Other'"
        },
        "required_count": {
          "type": "integer",
          "title": "Required Count",
          "description": "Number of recommendations of this type required"
        }
      },
      "required": [
        "program_id",
        "requirement_type",
        "required_count"
      ]
    }

Tool response:
Tool: create_deadline_rule
Description: Create Deadline Rule
Parameters:
    {
      "type": "object",
      "properties": {
        "program_id": {
          "type": "integer",
          "title": "Program Id",
          "description": ""
        },
        "rule_name": {
          "type": "string",
          "title": "Rule Name",
          "description": "Name of the rule"
        },
        "deadline_type": {
          "type": "string",
          "title": "Deadline Type",
          "description": "Type of deadline: 'Recommendation Submission', 'Final Application', or 'Other'"
        },
        "deadline_date": {
          "type": "string",
          "title": "Deadline Date",
          "description": "The date and time when the deadline occurs (ISO-8601)"
        },
        "action_on_missing": {
          "type": "string",
          "title": "Action On Missing",
          "description": "Action to take if items are missing: 'Waitlist Review', 'Reject', or 'Notify'"
        }
      },
      "required": [
        "program_id",
        "rule_name",
        "deadline_type",
        "deadline_date",
        "action_on_missing"
      ]
    }

Tool response:
Tool: create_reminder_schedule
Description: Create Reminder Schedule
Parameters:
    {
      "type": "object",
      "properties": {
        "program_id": {
          "type": "integer",
          "title": "Program Id",
          "description": ""
        },
        "reminder_type": {
          "type": "string",
          "title": "Reminder Type",
          "description": "Type of reminder: 'Recommendation Incomplete', 'Application Incomplete', or 'Other'"
        },
        "interval_days": {
          "type": "integer",
          "title": "Interval Days",
          "description": "Number of days between reminders"
        },
        "start_date": {
          "type": "string",
          "title": "Start Date",
          "description": "Date and time when reminders begin (ISO-8601)"
        },
        "end_date": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "End Date",
          "description": "Optional date and time when reminders stop (ISO-8601)"
        }
      },
      "required": [
        "program_id",
        "reminder_type",
        "interval_days",
        "start_date"
      ]
    }
